// A Verus program that, given an integer vector `valores` of length in [20,50),
// and three distinct indices i,j,k, returns a pair of those indices corresponding
// to the two largest values among valores[i], valores[j], valores[k], in
// non‐increasing order.

verus! {

    // Specification helper to pick out the "third" index not equal to x or y
    #[verus]
    spec fn third(i: usize, j: usize, k: usize, x: usize, y: usize) -> usize {
        if i != x && i != y { i }
        else if j != x && j != y { j }
        else { k }
    }

    #[verus]
    fn torneo(valores: &Vec<int>, i: usize, j: usize, k: usize) -> (usize, usize)
        requires
            // length constraints
            20 <= valores.len() && valores.len() < 50,
            // indices in bounds and distinct
            i < valores.len(),
            j < valores.len(),
            k < valores.len(),
            i != j,
            i != k,
            j != k,
        ensures
            // we only return two of {i,j,k}, and they are distinct
            let (x,y) = result;
            (x == i || x == j || x == k)
            && (y == i || y == j || y == k)
            && x != y
            // the values are in non‐increasing order
            && valores[x] >= valores[y]
            // and the third index (outside of x,y) satisfies valores[y] >= valores[z]
            && {
                let z = third(i, j, k, x, y);
                valores[y] >= valores[z]
            }
    {
        let vi = valores[i];
        let vj = valores[j];
        let vk = valores[k];

        if vi >= vj {
            if vj >= vk {
                // vi >= vj >= vk  ⇒ top two are i,j
                (i, j)
            } else {
                // vi >= vj but vj < vk
                if vi >= vk {
                    // vi >= vk > vj ⇒ top two are i,k
                    (i, k)
                } else {
                    // vk > vi >= vj ⇒ top two are k,i
                    (k, i)
                }
            }
        } else {
            // vj > vi
            if vi >= vk {
                // vj > vi >= vk ⇒ top two are j,i
                (j, i)
            } else if vj >= vk {
                // vj >= vk > vi ⇒ top two are j,k
                (j, k)
            } else {
                // vk > vj > vi ⇒ top two are k,j
                (k, j)
            }
        }
    }
}